from pathlib import Path
import json,shutil
b=Path('Library/WorkshopBackups/DB-ON-099'); b.mkdir(parents=True,exist_ok=True)
for src,name in [('Assets/Scenes/LobbyIslandWorkshop.unity','LobbyIslandWorkshop.before.unity'),('Assets/Igrodelnya/Localization/LocalizationData.asset','LocalizationData.before.asset')]:shutil.copy2(src,b/name)
code=r'''using System;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;
public static class Inspect099{static string BoundsText(Transform t){var rs=t.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b.ToString();}public static string Run(){var root=GameObject.Find("Lobby_Island_Visual_Prototype").transform;var main=root.Find("01_Central_Island");var b=new StringBuilder();foreach(var board in main.Find("03_Leaderboard_Common").Cast<Transform>().Where(t=>t.name.StartsWith("Leaderboard_")))b.AppendLine(board.name+" main="+main.InverseTransformPoint(board.position)+" bounds="+BoundsText(board));var salon=root.Find("04_Boat_Skins_Showcase");b.AppendLine("SALON main="+main.InverseTransformPoint(salon.position));foreach(var t in salon.GetComponentsInChildren<Transform>())if(t.name.Contains("Entrance")||t.name.Contains("Header")||t.name.Contains("Bridge")||t.name.Contains("UI096"))b.AppendLine(t.name+" main="+main.InverseTransformPoint(t.position)+" scale="+t.localScale);foreach(Transform t in main.Find("Bank_Crystal_Boutique095"))b.AppendLine("BANK "+t.name+" local="+t.localPosition+" scale="+t.localScale+" active="+t.gameObject.activeSelf);System.IO.File.WriteAllText("Library/WorkshopBackups/DB-ON-099/inspect.txt",b.ToString());return b.ToString();}}'''
(b/'inspect.json').write_text(json.dumps({'csharpCode':code,'className':'Inspect099','methodName':'Run'}),encoding='utf-8')
